def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 474.07137173160174  # OPT_PARAM: {"initial": 474.07137173160174, "min": 350, "max": 500, "type": "float"}
    safety_factor = 1.897511090816867  # OPT_PARAM: {"initial": 1.897511090816867, "min": 0.5, "max": 2.0, "type": "float"}
    order_cap = 96.58486118769336  # OPT_PARAM: {"initial": 96.58486118769336, "min": 80, "max": 150, "type": "float"}
    pipeline_weight = 0.5  # OPT_PARAM: {"initial": 0.5, "min": 0.0, "max": 0.5, "type": "float"}
    demand_buffer = 12.957998568220994  # OPT_PARAM: {"initial": 12.957998568220994, "min": 0, "max": 30, "type": "float"}

    # Calculate inventory position
    inventory_position = on_hand_inventory + sum(pipeline_orders)

    # Simple base-stock policy with demand buffer
    target_order = base_stock + demand_buffer - inventory_position

    # Apply pipeline-weighted smoothing
    if len(pipeline_orders) > 0:
        recent_pipeline = pipeline_orders[-1]
        smoothed_target = (1 - pipeline_weight) * target_order + pipeline_weight * recent_pipeline
    else:
        smoothed_target = target_order

    # Add safety adjustment based on pipeline variability
    if len(pipeline_orders) > 0:
        avg_pipeline = sum(pipeline_orders) / len(pipeline_orders)
        pipeline_var = sum((q - avg_pipeline) ** 2 for q in pipeline_orders) / len(pipeline_orders)
        pipeline_std = max(0, pipeline_var) ** 0.5
        safety_adjustment = safety_factor * pipeline_std
        final_target = smoothed_target + safety_adjustment
    else:
        final_target = smoothed_target

    # Cap the order amount and ensure non-negative
    order_amount = max(0, min(final_target, order_cap))

    return order_amount
